package com.campusevents.service;
import com.campusevents.dao.RegistrationDAO;import com.campusevents.model.*;import java.util.*;
public class RegistrationService {private final RegistrationDAO dao=new RegistrationDAO();public String register(User u,int event)throws Exception{if(!(u instanceof Student s))throw new SecurityException("Only students can register.");return dao.register(s.getStudentId(),event);}public void cancel(User u,String id)throws Exception{if(!(u instanceof Student s))throw new SecurityException("Student access required.");dao.cancel(id,s.getStudentId());}public List<String[]> mine(User u)throws Exception{if(!(u instanceof Student s))throw new SecurityException("Student access required.");return dao.mine(s.getStudentId());}public List<String[]> participants(User u,int event)throws Exception{if(!(u instanceof Admin))throw new SecurityException("Administrator access required.");return dao.participants(event);}}
